{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Tolbutamide, the closest structural analogue sharing the p-toluenesulfonyl carbonyl/sulfonylurea-like core, has absolute oral bioavailability of 80% in humans at therapeutic doses, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Glimepiride, a sulfonylurea with a bulky lipophilic amine substituent, is essentially completely bioavailable with 97% absolute oral bioavailability in healthy volunteers, supporting high oral bioavailability for the related sulfonylurea scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Even the more polar and poorly absorbed sulfonamide levosulpiride has absolute oral bioavailability of 23.4%, above the 20% threshold; the query is more lipophilic and neutral, so it is expected to be at least as bioavailable.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a p-toluenesulfonyl acylhydrazide with a lipophilic bicyclic amine, closely related to sulfonylureas such as tolbutamide and glimepiride, which show high (80–100%) oral bioavailability. Even poorly absorbed sulfonamide analogues exceed the 20% threshold, so the query is predicted to have high absolute oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the exact query molecule.",
    "The hydrazide and bicyclic amine moieties are not present in the closest high-bioavailability analogues, so their effects on absorption and first-pass metabolism are inferred rather than directly measured.",
    "Tolperisone is reported as having very low oral bioavailability, but no quantitative threshold-specific value is provided and its structural similarity to the query is low."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C41"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "sulfonylurea antidiabetics"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C07"],
      "decision_effect": "strengthened",
