      "family": "sulfonylurea antidiabetics"
    },
    {
      "applicability": "low",
      "card_ids": ["C44"],
      "decision_effect": "no_change",
      "direction": "supportive",
      "family": "sulfonamide antipsychotics"
    }
  ],
  "revision_action": "initial"
}

